    'Waktu database' => ["Database time", "数据库时间", "データベースの時刻", "وقت قاعدة البيانات", "Heure de la base de données", "Datenbankzeit", "Hora de la base de datos"],
    'Batas memori PHP' => ["PHP memory limit", "PHP内存上限", "PHPのメモリ上限", "حد ذاكرة PHP", "Limite de mémoire PHP", "PHP-Speicherlimit", "Límite de memoria de PHP"],

    // infraAdmin: cadangan
    'Unduh cadangan' => ["Download backup", "下载备份", "バックアップをダウンロード", "تنزيل نسخة احتياطية", "Télécharger une sauvegarde", "Sicherung herunterladen", "Descargar copia de seguridad"],
    'Berkas berisi seluruh isi database dalam bentuk SQL: anggota, KPI, realisasi, pengaturan, dan akun admin. Password tersimpan dalam bentuk acak (hash), tetapi berkas ini tetap rahasia. Simpan di tempat yang aman.' => ["The file contains the entire database as SQL: members, KPIs, actuals, settings and admin accounts. Passwords are stored scrambled (hashed), but the file is still confidential. Keep it somewhere safe.", "该文件以SQL格式包含整个数据库：成员、KPI、实际值、设置和管理员账户。密码以加密（哈希）形式保存，但此文件仍属机密，请妥善保管。", "ファイルにはデータベース全体がSQL形式で含まれます：メンバー、KPI、実績、設定、管理者アカウント。パスワードはハッシュ化されていますが、このファイルは機密です。安全な場所に保管してください。", "يحتوي الملف على قاعدة البيانات كاملة بصيغة SQL: الأعضاء ومؤشرات الأداء والنتائج والإعدادات وحسابات المشرفين. كلمات المرور محفوظة بشكل مُعمّى (hash)، لكن الملف يبقى سريًا. احفظه في مكان آمن.", "Le fichier contient toute la base de données au format SQL : membres, KPI, résultats, paramètres et comptes administrateur. Les mots de passe sont stockés sous forme chiffrée (hachage), mais le fichier reste confidentiel. Conservez-le en lieu sûr.", "Die Datei enthält die gesamte Datenbank als SQL: Mitglieder, KPIs, Ist-Werte, Einstellungen und Admin-Konten. Passwörter sind verschlüsselt (Hash) gespeichert, die Datei bleibt aber vertraulich. Bewahren Sie sie sicher auf.", "El archivo contiene toda la base de datos en SQL: miembros, KPI, resultados, configuración y cuentas de administrador. Las contraseñas se guardan cifradas (hash), pero el archivo sigue siendo confidencial. Guárdelo en un lugar seguro."],
    'Cadangan terakhir diunduh: {0}' => ["Last backup downloaded: {0}", "上次下载备份：{0}", "最後にバックアップをダウンロードした日時：{0}", "آخر تنزيل لنسخة احتياطية: {0}", "Dernière sauvegarde téléchargée : {0}", "Letzte Sicherung heruntergeladen: {0}", "Última copia descargada: {0}"],
    'belum pernah' => ["never", "从未", "まだありません", "لم يحدث بعد", "jamais", "noch nie", "nunca"],
    'Unduh cadangan (.sql)' => ["Download backup (.sql)", "下载备份（.sql）", "バックアップをダウンロード（.sql）", "تنزيل نسخة احتياطية (.sql)", "Télécharger la sauvegarde (.sql)", "Sicherung herunterladen (.sql)", "Descargar copia (.sql)"],
    'Cara memulihkan' => ["How to restore", "如何恢复", "復元の方法", "طريقة الاستعادة", "Comment restaurer", "So stellen Sie wieder her", "Cómo restaurar"],
    'Nyalakan mode pemeliharaan supaya tidak ada yang mengisi data selama pemulihan.' => ["Turn on maintenance mode so nobody enters data during the restore.", "开启维护模式，避免恢复期间有人录入数据。", "復元中に誰もデータを入力しないよう、メンテナンスモードをオンにします。", "شغّل وضع الصيانة حتى لا يُدخل أحد بيانات أثناء الاستعادة.", "Activez le mode maintenance pour que personne ne saisisse de données pendant la restauration.", "Schalten Sie den Wartungsmodus ein, damit während der Wiederherstellung niemand Daten erfasst.", "Active el modo de mantenimiento para que nadie introduzca datos durante la restauración."],
    'Buka phpMyAdmin, pilih database aplikasi, lalu buka menu {0}.' => ["Open phpMyAdmin, choose the app's database, then open the {0} menu.", "打开phpMyAdmin，选择应用的数据库，然后打开{0}菜单。", "phpMyAdminを開き、アプリのデータベースを選んで{0}メニューを開きます。", "افتح phpMyAdmin واختر قاعدة بيانات التطبيق، ثم افتح قائمة {0}.", "Ouvrez phpMyAdmin, choisissez la base de données de l'application, puis le menu {0}.", "Öffnen Sie phpMyAdmin, wählen Sie die Datenbank der App und öffnen Sie das Menü {0}.", "Abra phpMyAdmin, elija la base de datos de la aplicación y abra el menú {0}."],
    'Pilih berkas cadangan {0}, lalu klik {1}. Isi database diganti dengan isi cadangan.' => ["Choose the {0} backup file, then click {1}. The database contents are replaced with the backup.", "选择{0}备份文件，然后点击{1}。数据库内容将被备份内容替换。", "{0}のバックアップファイルを選んで{1}をクリックします。データベースの内容がバックアップの内容に置き換わります。", "اختر ملف النسخة الاحتياطية {0}، ثم انقر {1}. سيُستبدل محتوى قاعدة البيانات بمحتوى النسخة.", "Choisissez le fichier de sauvegarde {0}, puis cliquez sur {1}. Le contenu de la base est remplacé par celui de la sauvegarde.", "Wählen Sie die Sicherungsdatei {0} und klicken Sie auf {1}. Der Datenbankinhalt wird durch die Sicherung ersetzt.", "Elija el archivo de copia {0} y haga clic en {1}. El contenido de la base de datos se sustituye por el de la copia."],
    'Matikan kembali mode pemeliharaan.' => ["Turn maintenance mode off again.", "再次关闭维护模式。", "メンテナンスモードをオフに戻します。", "أوقف وضع الصيانة مجددًا.", "Désactivez à nouveau le mode maintenance.", "Schalten Sie den Wartungsmodus wieder aus.", "Vuelva a desactivar el modo de mantenimiento."],
    'Pemulihan sengaja tidak disediakan sebagai tombol di halaman ini, supaya data tidak tertimpa karena salah klik.' => ["Restoring is deliberately not offered as a button on this page, so data is not overwritten by a wrong click.", "此页面特意不提供恢复按钮，以免误点导致数据被覆盖。", "誤ってクリックしてデータが上書きされないよう、このページには復元ボタンをあえて用意していません。", "لم تُوفَّر الاستعادة كزر في هذه الصفحة عمدًا، حتى لا تُستبدل البيانات بنقرة خاطئة.", "La restauration n'est volontairement pas proposée sous forme de bouton sur cette page, pour éviter d'écraser les données par erreur.", "Die Wiederherstellung gibt es hier absichtlich nicht als Schaltfläche, damit Daten nicht durch einen Fehlklick überschrieben werden.", "La restauración no se ofrece a propósito como botón en esta página, para que un clic por error no sobrescriba los datos."],

    // infraAdmin: mode pemeliharaan
    'Keadaan sekarang: {0}' => ["Current state: {0}", "当前状态：{0}", "現在の状態：{0}", "الحالة الآن: {0}", "État actuel : {0}", "Aktueller Zustand: {0}", "Estado actual: {0}"],
    'Saat mode pemeliharaan aktif, aplikasi KPI menampilkan halaman pemberitahuan dan tidak ada yang bisa masuk atau mengisi data. Halaman admin ini tetap bisa dibuka. Pakai saat memulihkan cadangan atau memperbarui aplikasi.' => ["While maintenance mode is on, the KPI app shows a notice page and nobody can sign in or enter data. This admin page stays available. Use it while restoring a backup or updating the app.", "维护模式开启时，KPI应用会显示通知页面，任何人都无法登录或录入数据。此管理页面仍可访问。请在恢复备份或更新应用时使用。", "メンテナンスモードがオンの間、KPIアプリはお知らせページを表示し、誰もログインやデータ入力ができません。この管理ページは引き続き使えます。バックアップの復元やアプリの更新時に使ってください。", "أثناء تفعيل وضع الصيانة، يعرض تطبيق KPI صفحة إشعار ولا يمكن لأحد تسجيل الدخول أو إدخال البيانات. تبقى صفحة الإدارة هذه متاحة. استخدمه عند استعادة نسخة احتياطية أو تحديث التطبيق.", "Pendant le mode maintenance, l'application KPI affiche une page d'information et personne ne peut se connecter ni saisir de données. Cette page d'administration reste accessible. Utilisez-le pendant une restauration ou une mise à jour de l'application.", "Im Wartungsmodus zeigt die KPI-App eine Hinweisseite, und niemand kann sich anmelden oder Daten erfassen. Diese Admin-Seite bleibt erreichbar. Nutzen Sie ihn beim Wiederherstellen einer Sicherung oder beim Aktualisieren der App.", "Mientras el modo de mantenimiento está activado, la aplicación de KPI muestra una página de aviso y nadie puede iniciar sesión ni introducir datos. Esta página de administración sigue disponible. Úselo al restaurar una copia o actualizar la aplicación."],
    'Tutup aplikasi sementara' => ["Close the app temporarily", "暂时关闭应用", "アプリを一時的に閉鎖する", "إغلاق التطبيق مؤقتًا", "Fermer temporairement l'application", "App vorübergehend schließen", "Cerrar la aplicación temporalmente"],
    'Hilangkan centang untuk membuka aplikasi kembali.' => ["Untick to open the app again.", "取消勾选即可重新开放应用。", "チェックを外すとアプリが再び使えるようになります。", "أزل علامة الاختيار لإعادة فتح التطبيق.", "Décochez pour rouvrir l'application.", "Haken entfernen, um die App wieder zu öffnen.", "Desmarque para volver a abrir la aplicación."],
    'Pesan untuk anggota' => ["Message for members", "给成员的消息", "メンバーへのメッセージ", "رسالة للأعضاء", "Message pour les membres", "Nachricht an die Mitglieder", "Mensaje para los miembros"],
    'Contoh: Aplikasi sedang diperbarui dan bisa dipakai lagi pukul 13.00.' => ["Example: The app is being updated and will be available again at 1:00 pm.", "例如：应用正在更新，将于13:00恢复使用。", "例：アプリを更新中です。13:00から再びご利用いただけます。", "مثال: يجري تحديث التطبيق وسيكون متاحًا مجددًا الساعة 13:00.", "Exemple : L'application est en cours de mise à jour et sera de nouveau disponible à 13 h.", "Beispiel: Die App wird aktualisiert und ist ab 13:00 Uhr wieder verfügbar.", "Ejemplo: La aplicación se está actualizando y volverá a estar disponible a las 13:00."],
    'Bila dikosongkan, anggota melihat pesan bawaan dalam bahasa yang mereka pilih.' => ["If left empty, members see the default message in the language they chose.", "如留空，成员将看到其所选语言的默认消息。", "空欄の場合、メンバーには選択した言語の標準メッセージが表示されます。", "إذا تُركت فارغة، يرى الأعضاء الرسالة الافتراضية باللغة التي اختاروها.", "Si le champ est vide, les membres voient le message par défaut dans la langue qu'ils ont choisie.", "Bleibt das Feld leer, sehen die Mitglieder die Standardnachricht in ihrer gewählten Sprache.", "Si se deja vacío, los miembros ven el mensaje predeterminado en el idioma que eligieron."],
    'Lihat tampilan aplikasi' => ["View the app", "查看应用页面", "アプリの表示を確認", "عرض التطبيق", "Voir l'application", "App ansehen", "Ver la aplicación"],

    // Catatan aktivitas
    '{0} kegiatan terakhir' => ["Last {0} activities", "最近{0}条活动", "直近{0}件のアクティビティ", "آخر {0} نشاط", "{0} dernières activités", "Letzte {0} Aktivitäten", "Últimas {0} actividades"],
    '{0} baris' => ["{0} rows", "{0}行", "{0}行", "{0} صف", "{0} lignes", "{0} Zeilen", "{0} filas"],
    'Bersihkan catatan lama' => ["Clean up old records", "清理旧记录", "古い記録を削除", "تنظيف السجلات القديمة", "Nettoyer les anciennes entrées", "Alte Einträge bereinigen", "Limpiar registros antiguos"],
    'Catatan aktivitas terus bertambah. Hapus yang sudah lama supaya database tetap ringan. Data KPI tidak terpengaruh.' => ["The activity log keeps growing. Delete old entries to keep the database light. KPI data is not affected.", "活动记录会不断增加。删除旧记录可让数据库保持轻量，KPI数据不受影响。", "アクティビティログは増え続けます。古い記録を削除してデータベースを軽く保ちましょう。KPIデータには影響しません。", "يزداد سجل النشاط باستمرار. احذف الإدخالات القديمة ليبقى حجم قاعدة البيانات صغيرًا. لا تتأثر بيانات مؤشرات الأداء.", "Le journal d'activité ne cesse de grossir. Supprimez les anciennes entrées pour alléger la base de données. Les données KPI ne sont pas touchées.", "Das Aktivitätsprotokoll wächst ständig. Löschen Sie alte Einträge, damit die Datenbank schlank bleibt. KPI-Daten sind nicht betroffen.", "El registro de actividad crece sin parar. Elimine las entradas antiguas para mantener ligera la base de datos. Los datos de KPI no se ven afectados."],
    'Hapus catatan yang lebih lama dari' => ["Delete records older than", "删除早于以下时间的记录", "次より古い記録を削除", "حذف السجلات الأقدم من", "Supprimer les entrées de plus de", "Einträge löschen, die älter sind als", "Eliminar registros con más de"],
    '1 tahun' => ["1 year", "1年", "1年", "سنة واحدة", "1 an", "1 Jahr", "1 año"],
    '6 bulan' => ["6 months", "6个月", "6か月", "6 أشهر", "6 mois", "6 Monate", "6 meses"],
    '3 bulan' => ["3 months", "3个月", "3か月", "3 أشهر", "3 mois", "3 Monate", "3 meses"],
