    // Pemberitahuan setelah tindakan (admin.php)
    'Sesi sudah berakhir. Silakan ulangi.' => ["The session has expired. Please try again.", "会话已过期，请重试。", "セッションの有効期限が切れました。もう一度お試しください。", "انتهت الجلسة. يُرجى المحاولة مرة أخرى.", "La session a expiré. Veuillez réessayer.", "Die Sitzung ist abgelaufen. Bitte erneut versuchen.", "La sesión ha caducado. Inténtelo de nuevo."],
    'Akun admin sudah dibuat. Silakan masuk.' => ["The admin account has been created. Please sign in.", "管理员账户已创建，请登录。", "管理者アカウントを作成しました。ログインしてください。", "تم إنشاء حساب المشرف. يُرجى تسجيل الدخول.", "Le compte administrateur a été créé. Veuillez vous connecter.", "Das Admin-Konto wurde erstellt. Bitte melden Sie sich an.", "Se ha creado la cuenta de administrador. Inicie sesión."],
    'Silakan masuk terlebih dahulu.' => ["Please sign in first.", "请先登录。", "先にログインしてください。", "يُرجى تسجيل الدخول أولًا.", "Veuillez d'abord vous connecter.", "Bitte melden Sie sich zuerst an.", "Inicie sesión primero."],
    'Tindakan ini hanya untuk {0}.' => ["This action is only for {0}.", "此操作仅限{0}。", "この操作は{0}専用です。", "هذا الإجراء مخصّص لـ {0} فقط.", "Cette action est réservée au {0}.", "Diese Aktion ist nur für {0}.", "Esta acción es solo para {0}."],
    'Password saat ini salah.' => ["The current password is incorrect.", "当前密码不正确。", "現在のパスワードが正しくありません。", "كلمة المرور الحالية غير صحيحة.", "Le mot de passe actuel est incorrect.", "Das aktuelle Passwort ist falsch.", "La contraseña actual es incorrecta."],
    'Ulangi password baru dengan isi yang sama.' => ["Repeat the new password exactly.", "请再次输入相同的新密码。", "新しいパスワードを同じ内容でもう一度入力してください。", "أعد إدخال كلمة المرور الجديدة نفسها.", "Répétez exactement le nouveau mot de passe.", "Wiederholen Sie das neue Passwort genau gleich.", "Repita exactamente la nueva contraseña."],
    'Password Anda sudah diganti.' => ["Your password has been changed.", "您的密码已修改。", "パスワードを変更しました。", "تم تغيير كلمة المرور.", "Votre mot de passe a été modifié.", "Ihr Passwort wurde geändert.", "Su contraseña se ha cambiado."],
    'Data anggota "{0}" sudah disimpan.' => ["Member “{0}” has been saved.", "成员“{0}”的资料已保存。", "メンバー「{0}」の情報を保存しました。", "تم حفظ بيانات العضو «{0}».", "Le membre « {0} » a été enregistré.", "Mitglied „{0}“ wurde gespeichert.", "Se han guardado los datos del miembro «{0}»."],
    'Akun "{0}" diaktifkan kembali.' => ["Account “{0}” has been reactivated.", "账户“{0}”已重新启用。", "アカウント「{0}」を再度有効にしました。", "تمت إعادة تفعيل الحساب «{0}».", "Le compte « {0} » a été réactivé.", "Konto „{0}“ wurde wieder aktiviert.", "Se ha reactivado la cuenta «{0}»."],
    'Akun "{0}" dinonaktifkan dan tidak bisa masuk.' => ["Account “{0}” has been deactivated and cannot sign in.", "账户“{0}”已停用，无法登录。", "アカウント「{0}」を無効にしました。ログインできません。", "تم تعطيل الحساب «{0}» ولا يمكنه تسجيل الدخول.", "Le compte « {0} » a été désactivé et ne peut plus se connecter.", "Konto „{0}“ wurde deaktiviert und kann sich nicht anmelden.", "Se ha desactivado la cuenta «{0}» y no puede iniciar sesión."],
    'Akun CEO tidak dapat dihapus.' => ["The CEO account cannot be deleted.", "CEO账户无法删除。", "CEOのアカウントは削除できません。", "لا يمكن حذف حساب الرئيس التنفيذي.", "Le compte du CEO ne peut pas être supprimé.", "Das CEO-Konto kann nicht gelöscht werden.", "La cuenta del CEO no se puede eliminar."],
    'Anggota "{0}" beserta KPI miliknya sudah dihapus.' => ["Member “{0}” and their KPIs have been deleted.", "成员“{0}”及其KPI已删除。", "メンバー「{0}」とそのKPIを削除しました。", "تم حذف العضو «{0}» مع مؤشرات أدائه.", "Le membre « {0} » et ses KPI ont été supprimés.", "Mitglied „{0}“ und seine KPIs wurden gelöscht.", "Se han eliminado el miembro «{0}» y sus KPI."],
    'Kunci login sudah dibuka.' => ["The sign-in lock has been removed.", "登录锁定已解除。", "ログインのロックを解除しました。", "تم فتح قفل تسجيل الدخول.", "Le blocage de connexion a été levé.", "Die Anmeldesperre wurde aufgehoben.", "Se ha quitado el bloqueo de inicio de sesión."],
    'Nama perusahaan wajib diisi.' => ["Company name is required.", "公司名称为必填项。", "会社名は必須です。", "اسم الشركة مطلوب.", "Le nom de l'entreprise est obligatoire.", "Der Firmenname ist erforderlich.", "El nombre de la empresa es obligatorio."],
    'Batas capaian harus antara 100 dan 200 persen.' => ["The achievement cap must be between 100 and 200 percent.", "达成上限必须在100%到200%之间。", "達成率の上限は100〜200％の範囲にしてください。", "يجب أن يكون الحد الأقصى للإنجاز بين 100 و200 في المئة.", "Le plafond d'atteinte doit être compris entre 100 et 200 %.", "Die Obergrenze muss zwischen 100 und 200 Prozent liegen.", "El límite de logro debe estar entre el 100 y el 200 %."],
    'Tahun tidak valid.' => ["Invalid year.", "年度无效。", "年度が無効です。", "السنة غير صالحة.", "Année non valide.", "Ungültiges Jahr.", "Año no válido."],
    'Pengaturan aplikasi sudah disimpan.' => ["App settings have been saved.", "应用设置已保存。", "アプリ設定を保存しました。", "تم حفظ إعدادات التطبيق.", "Les paramètres de l'application ont été enregistrés.", "Die App-Einstellungen wurden gespeichert.", "Se ha guardado la configuración de la aplicación."],
    'Akun admin "{0}" sudah disimpan.' => ["Admin account “{0}” has been saved.", "管理员账户“{0}”已保存。", "管理者アカウント「{0}」を保存しました。", "تم حفظ حساب المشرف «{0}».", "Le compte administrateur « {0} » a été enregistré.", "Admin-Konto „{0}“ wurde gespeichert.", "Se ha guardado la cuenta de administrador «{0}»."],
    'Akun admin "{0}" diaktifkan kembali.' => ["Admin account “{0}” has been reactivated.", "管理员账户“{0}”已重新启用。", "管理者アカウント「{0}」を再度有効にしました。", "تمت إعادة تفعيل حساب المشرف «{0}».", "Le compte administrateur « {0} » a été réactivé.", "Admin-Konto „{0}“ wurde wieder aktiviert.", "Se ha reactivado la cuenta de administrador «{0}»."],
    'Akun admin "{0}" dinonaktifkan.' => ["Admin account “{0}” has been deactivated.", "管理员账户“{0}”已停用。", "管理者アカウント「{0}」を無効にしました。", "تم تعطيل حساب المشرف «{0}».", "Le compte administrateur « {0} » a été désactivé.", "Admin-Konto „{0}“ wurde deaktiviert.", "Se ha desactivado la cuenta de administrador «{0}»."],
    'Akun admin "{0}" sudah dihapus.' => ["Admin account “{0}” has been deleted.", "管理员账户“{0}”已删除。", "管理者アカウント「{0}」を削除しました。", "تم حذف حساب المشرف «{0}».", "Le compte administrateur « {0} » a été supprimé.", "Admin-Konto „{0}“ wurde gelöscht.", "Se ha eliminado la cuenta de administrador «{0}»."],
    'Mode pemeliharaan aktif. Aplikasi ditutup sementara untuk semua anggota.' => ["Maintenance mode is on. The app is temporarily closed to all members.", "维护模式已开启。应用已对所有成员暂时关闭。", "メンテナンスモードをオンにしました。アプリはすべてのメンバーに対して一時的に閉鎖されています。", "تم تفعيل وضع الصيانة. التطبيق مغلق مؤقتًا أمام جميع الأعضاء.", "Le mode maintenance est activé. L'application est temporairement fermée à tous les membres.", "Der Wartungsmodus ist aktiv. Die App ist für alle Mitglieder vorübergehend geschlossen.", "El modo de mantenimiento está activado. La aplicación está cerrada temporalmente para todos los miembros."],
    'Mode pemeliharaan dimatikan. Aplikasi bisa dipakai kembali.' => ["Maintenance mode is off. The app can be used again.", "维护模式已关闭。应用可以重新使用。", "メンテナンスモードをオフにしました。アプリを再び使えます。", "تم إيقاف وضع الصيانة. يمكن استخدام التطبيق مجددًا.", "Le mode maintenance est désactivé. L'application est de nouveau utilisable.", "Der Wartungsmodus ist aus. Die App kann wieder genutzt werden.", "El modo de mantenimiento está desactivado. La aplicación se puede volver a usar."],
    'Pilih batas umur catatan.' => ["Choose how old the records must be.", "请选择记录的保留期限。", "削除する記録の期間を選んでください。", "اختر عمر السجلات المراد حذفها.", "Choisissez l'ancienneté des entrées.", "Wählen Sie das Alter der Einträge.", "Elija la antigüedad de los registros."],
    '{0} catatan yang lebih lama dari {1} hari sudah dihapus.' => ["{0} record(s) older than {1} days have been deleted.", "已删除{0}条超过{1}天的记录。", "{1}日より古い記録を{0}件削除しました。", "تم حذف {0} من السجلات الأقدم من {1} يومًا.", "{0} entrée(s) de plus de {1} jours ont été supprimées.", "{0} Einträge, die älter als {1} Tage sind, wurden gelöscht.", "Se han eliminado {0} registros con más de {1} días."],
    'Tindakan tidak dikenal.' => ["Unknown action.", "未知操作。", "不明な操作です。", "إجراء غير معروف.", "Action inconnue.", "Unbekannte Aktion.", "Acción desconocida."],
    'Halaman admin bermasalah' => ["Admin page error", "管理页面出错", "管理ページのエラー", "خطأ في صفحة الإدارة", "Erreur de la page d'administration", "Fehler auf der Admin-Seite", "Error en la página de administración"],
    'Halaman admin tidak dapat dibuka' => ["The admin page cannot be opened", "无法打开管理页面", "管理ページを開けません", "تعذّر فتح صفحة الإدارة", "Impossible d'ouvrir la page d'administration", "Die Admin-Seite kann nicht geöffnet werden", "No se puede abrir la página de administración"],
    'Aplikasi tidak dapat terhubung ke database, atau terjadi galat di server. Pastikan MySQL menyala, lalu muat ulang halaman ini. Rincian teknis dicatat di log error server.' => ["The app cannot connect to the database, or a server error occurred. Make sure MySQL is running, then reload this page. Technical details are written to the server error log.", "应用无法连接到数据库，或服务器发生错误。请确认MySQL正在运行，然后重新加载此页面。技术细节已记录在服务器错误日志中。", "アプリがデータベースに接続できないか、サーバーでエラーが発生しました。MySQLが起動していることを確認してから、このページを再読み込みしてください。技術的な詳細はサーバーのエラーログに記録されています。", "تعذّر على التطبيق الاتصال بقاعدة البيانات، أو حدث خطأ في الخادم. تأكد من تشغيل MySQL، ثم أعد تحميل هذه الصفحة. التفاصيل التقنية مسجّلة في سجل أخطاء الخادم.", "L'application ne peut pas se connecter à la base de données, ou une erreur serveur s'est produite. Vérifiez que MySQL est démarré, puis rechargez cette page. Les détails techniques sont consignés dans le journal d'erreurs du serveur.", "Die App kann keine Verbindung zur Datenbank herstellen, oder auf dem Server ist ein Fehler aufgetreten. Stellen Sie sicher, dass MySQL läuft, und laden Sie die Seite neu. Technische Details stehen im Fehlerprotokoll des Servers.", "La aplicación no puede conectarse a la base de datos o se produjo un error en el servidor. Compruebe que MySQL está en marcha y vuelva a cargar esta página. Los detalles técnicos se registran en el log de errores del servidor."],

    // Pesan galat dari lib/admin.php
    'Username atau password salah.' => ["Incorrect username or password.", "用户名或密码错误。", "ユーザー名またはパスワードが正しくありません。", "اسم المستخدم أو كلمة المرور غير صحيحة.", "Nom d'utilisateur ou mot de passe incorrect.", "Benutzername oder Passwort ist falsch.", "Usuario o contraseña incorrectos."],
    'Akun ini adalah {0}. Silakan masuk lewat alamat {1}' => ["This is a {0} account. Please sign in at {1}", "这是{0}账户。请通过以下地址登录：{1}", "これは{0}のアカウントです。次のアドレスからログインしてください：{1}", "هذا حساب {0}. يُرجى تسجيل الدخول عبر العنوان {1}", "Ce compte est un compte {0}. Connectez-vous à l'adresse {1}", "Dies ist ein {0}-Konto. Bitte melden Sie sich hier an: {1}", "Esta es una cuenta {0}. Inicie sesión en {1}"],
    'Password admin minimal {0} karakter.' => ["Admin passwords must be at least {0} characters.", "管理员密码至少需要{0}个字符。", "管理者のパスワードは{0}文字以上にしてください。", "يجب ألا تقل كلمة مرور المشرف عن {0} أحرف.", "Le mot de passe administrateur doit comporter au moins {0} caractères.", "Admin-Passwörter müssen mindestens {0} Zeichen haben.", "La contraseña de administrador debe tener al menos {0} caracteres."],
    'Pilih peran sysAdmin atau infraAdmin.' => ["Choose the sysAdmin or infraAdmin role.", "请选择sysAdmin或infraAdmin角色。", "sysAdmin または infraAdmin の役割を選んでください。", "اختر دور sysAdmin أو infraAdmin.", "Choisissez le rôle sysAdmin ou infraAdmin.", "Wählen Sie die Rolle sysAdmin oder infraAdmin.", "Elija el rol sysAdmin o infraAdmin."],
    'Username "{0}" sudah dipakai admin lain.' => ["The username “{0}” is already used by another admin.", "用户名“{0}”已被其他管理员使用。", "ユーザー名「{0}」は他の管理者が使用しています。", "اسم المستخدم «{0}» مستخدم من قِبل مشرف آخر.", "Le nom d'utilisateur « {0} » est déjà utilisé par un autre administrateur.", "Der Benutzername „{0}“ wird bereits von einem anderen Admin verwendet.", "El usuario «{0}» ya lo usa otro administrador."],
    'Akun admin tidak ditemukan.' => ["Admin account not found.", "未找到该管理员账户。", "管理者アカウントが見つかりません。", "لم يتم العثور على حساب المشرف.", "Compte administrateur introuvable.", "Admin-Konto nicht gefunden.", "No se encontró la cuenta de administrador."],
    'Harus ada minimal satu sysAdmin yang aktif.' => ["There must be at least one active sysAdmin.", "必须至少保留一个启用的sysAdmin。", "有効なsysAdminが少なくとも1人必要です。", "يجب أن يوجد sysAdmin نشط واحد على الأقل.", "Il doit rester au moins un sysAdmin actif.", "Es muss mindestens einen aktiven sysAdmin geben.", "Debe haber al menos un sysAdmin activo."],
    'Anda tidak dapat menonaktifkan akun Anda sendiri.' => ["You cannot deactivate your own account.", "您不能停用自己的账户。", "自分のアカウントは無効にできません。", "لا يمكنك تعطيل حسابك.", "Vous ne pouvez pas désactiver votre propre compte.", "Sie können Ihr eigenes Konto nicht deaktivieren.", "No puede desactivar su propia cuenta."],
    'Akun sysAdmin sudah ada. Silakan masuk.' => ["A sysAdmin account already exists. Please sign in.", "sysAdmin账户已存在，请登录。", "sysAdminアカウントはすでにあります。ログインしてください。", "يوجد حساب sysAdmin بالفعل. يُرجى تسجيل الدخول.", "Un compte sysAdmin existe déjà. Veuillez vous connecter.", "Ein sysAdmin-Konto ist bereits vorhanden. Bitte melden Sie sich an.", "Ya existe una cuenta sysAdmin. Inicie sesión."],
    'Username atau password CEO salah.' => ["Incorrect CEO username or password.", "CEO用户名或密码错误。", "CEOのユーザー名またはパスワードが正しくありません。", "اسم المستخدم أو كلمة المرور الخاصة بالرئيس التنفيذي غير صحيحة.", "Nom d'utilisateur ou mot de passe du CEO incorrect.", "Benutzername oder Passwort des CEO ist falsch.", "Usuario o contraseña del CEO incorrectos."],
    'Username sysAdmin dan infraAdmin harus berbeda.' => ["The sysAdmin and infraAdmin usernames must be different.", "sysAdmin和infraAdmin的用户名必须不同。", "sysAdmin と infraAdmin のユーザー名は別にしてください。", "يجب أن يختلف اسم مستخدم sysAdmin عن infraAdmin.", "Les noms d'utilisateur sysAdmin et infraAdmin doivent être différents.", "Die Benutzernamen von sysAdmin und infraAdmin müssen sich unterscheiden.", "Los usuarios de sysAdmin e infraAdmin deben ser distintos."],
    'Akun CEO satu-satunya tidak dapat dinonaktifkan.' => ["The only CEO account cannot be deactivated.", "唯一的CEO账户无法停用。", "唯一のCEOアカウントは無効にできません。", "لا يمكن تعطيل حساب الرئيس التنفيذي الوحيد.", "Le seul compte CEO ne peut pas être désactivé.", "Das einzige CEO-Konto kann nicht deaktiviert werden.", "La única cuenta de CEO no se puede desactivar."],
];
